/* Builds Restaurant-Workspace-Preview-v19.html: the exact production shell, screens and styles,
   wired to an in-page sample backend so every button can be clicked. No network writes. */
'use strict';
const fs = require('fs'), path = require('path');
const root = path.resolve(__dirname, '..', 'WEBSITE'), suite = path.join(root, 'billing-suite');
const read = p => fs.readFileSync(p, 'utf8');
const script = s => '<script>' + s.replace(/<\/script/gi, '<\\/script') + '</script>';
const URL0 = 'https://preview-demo.supabase.co';
const b64 = o => Buffer.from(JSON.stringify(o)).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
const KEY = b64({ alg: 'HS256', typ: 'JWT' }) + '.' + b64({ role: 'anon', ref: 'preview-demo' }) + '.preview-signature-not-valid';

const config = `const RESTAURANT_CONFIG={publicMenuUrl:'https://yummy-momo.example/',restaurantName:'Aryan Momo wala',tagline:'Yummy in your big tummy',currency:'₹',supabaseUrl:'${URL0}',supabaseAnonKey:'${KEY}',googleReviewUrl:'',restaurantSlug:'preview',imagesBaseUrl:'',categories:['All'],menuItems:[]};`;
const boot = `
window.WORKSPACE_PREVIEW_NO_ENGINE=true;
(function(){
 const mock=window.PreviewMock(()=>{});window.__previewMock=mock;const s=mock.state,ago=n=>new Date(Date.now()-n*60000).toISOString();
 const more=[['m5','Veg Kurkure Momos','Kurkure Momos',110,true],['m6','Chicken Kurkure Momos','Kurkure Momos',150,false],['m7','Tandoori Paneer Momos','Tandoori Momos',160,true],['m8','Spicy Red Chutney','Chutney & Dips',20,true],['m9','Masala Lemon Soda','Drinks',60,true]];
 for(const [id,name,category,price,veg] of more)s.menu.push({id,name,category,price,veg,available:true,description:'',image:'',sizes_enabled:false,size_prices:{},size_labels:{},updated_at:ago(60),stock:{tracked:id!=='m9',remaining:id==='m8'?3:30}});
 s.orders.push({id:'o4',order_id:'QR-4',daily_number:44,table_number:'T2',customer_name:'Neha',created_at:ago(1),updated_at:ago(1),status:'Pending',order_source:'qr',device_id:'d2aaaaaaaaaaaa',payment_method:null,items:[{id:'m5',name:'Veg Kurkure Momos',qty:1,price:110,subtotal:110},{id:'m9',name:'Masala Lemon Soda',qty:2,price:60,subtotal:120}],items_subtotal:230,tax_amount:0,total:230,kitchen_notes:'Extra mayo'});
 const IMG={"m1": "data:image/webp;base64,", "m2": "data:image/webp;base64,", "m3": "data:image/webp;base64,", "m4": "data:image/webp;base64,", "m5": "data:image/webp;base64,", "m6": "data:image/webp;base64,", "m7": "data:image/webp;base64,"};for(const m of s.menu)if(IMG[m.id])m.image=IMG[m.id];s.menu.forEach(m=>{if(['m1','m6'].includes(m.id))m.best_seller=true;if(m.id==='m2')m.recommended=true;});
 Object.assign(s.custom,{m17:{arch:'classic',theme:'tomato',texts:{tagline:'Momos, noodles & more',location:'Sector 18 market, Noida',time:'Serving in 15–20 min',chip:'Frequently reordered',rating:'4.4',ratingCount:'By 6.9K+',about:'Open 11 am – 11 pm every day.'},offers:{mode:'one',insta:{on:true,handle:'aryanmomowala',amount:20},review:{on:true,url:'https://g.page/r/example/review',amount:50}}}});
 s.orders.push({id:'o5',order_id:'QR-5',daily_number:45,table_number:'T1',customer_name:'Kabir',created_at:ago(2),updated_at:ago(2),status:'Pending',order_source:'qr',device_id:'d3aaaaaaaaaaaa',payment_method:null,items:[{id:'m3',name:'Chicken Fried Momos',qty:1,price:140,subtotal:140}],items_subtotal:140,tax_enabled:false,tax_amount:0,total:90,discount_amount:50,offers:['review'],kitchen_notes:'Less spicy\\nOffer: Google review −₹50 (check before serving)'});
 s.tables.push({table_number:'T3',display_name:'Garden 1',status:'Available',qr_key:'qk-three'});
 const day=new Date().toISOString().slice(0,10);
 mock.docs.push({id:'e1',kind:'expense',doc_day:day.slice(0,8)+'01',data:{head:'Rent',title:'',amount:18000,method:'Bank',note:'',by:'Admin'},created_at:ago(5000),updated_at:ago(5000)},{id:'e2',kind:'expense',doc_day:day,data:{head:'Gas',title:'Cylinder',amount:1150,method:'Cash',note:'',by:'Admin'},created_at:ago(100),updated_at:ago(100)});
 const url='${URL0}',real=window.fetch.bind(window);
 const json=(o,st=200)=>new Response(JSON.stringify(o??null),{status:st,headers:{'content-type':'application/json'}});
 window.fetch=async(input,init={})=>{
  const u=new URL(typeof input==='string'?input:input.url,location.href);
  if(u.origin===url){let body=null;try{body=init.body?JSON.parse(init.body):null;}catch{}await new Promise(r=>setTimeout(r,120));
   try{return json(mock.handle(init.method||'GET',u.pathname+u.search,body));}catch(e){return json({message:e.message},e.status||400);}}
  return real(input,init);
 };
 const KEYS='YUMMY46:'+url+':public-device:RESTAURANT_STAFF_SESSION_v3';
 try{sessionStorage.setItem(KEYS,JSON.stringify({access_token:'preview',refresh_token:'preview',expires_at:Math.floor(Date.now()/1000)+86400,user:{id:'u-admin',email:'owner@aryanmomo.example'}}));}catch{}
})();`;
const after = `
/* Photos stay inside this page: no uploads in the preview. */
RestaurantCloud.patchMenu=async(id,body)=>{const m=window.__previewMock.state.menu.find(x=>x.id===id);if(m)Object.assign(m,body);return [];};
RestaurantCloud.deleteMenu=async id=>{const l=window.__previewMock.state.menu,i=l.findIndex(x=>x.id===id);if(i>=0)l.splice(i,1);return [];};
RestaurantCloud.logout=async()=>{toast('Sign out is turned off in this preview.','warn');throw Error('Sign out is turned off in this preview.');};
`;

let html = read(path.join(suite, 'index.src.html'));
html = html.replace(/<link\b[^>]*rel="(?:manifest|icon|apple-touch-icon)"[^>]*>/gi, '');
html = html.replace(/<link\b[^>]*rel="stylesheet"[^>]*href="([^"]+)"[^>]*>/gi, (tag, url) => url.startsWith('http') ? tag : '<style>' + read(path.join(suite, url.split('?')[0])) + '</style>');
html = html.replace('<script src="../config.js"></script>', script(config) + script(read(path.join(__dirname, 'preview-mock.js'))) + script(boot));
html = html.replace(/<script src="([^"]+)"><\/script>/gi, (_, url) => script(read(path.join(suite, url.split('?')[0]))) + (url.startsWith('restaurant-cloud.js') ? script(after) : ''));
html = html.replace("if ('serviceWorker' in navigator && location.protocol === 'https:')", 'if (false)');
html = html.replace('<title>Shop Billing</title>', '<title>Restaurant Workspace Preview</title>');
html = html.replace('</body>', '<div style="position:fixed;bottom:6px;right:6px;z-index:1000;font:600 11px system-ui;padding:3px 8px;border-radius:99px;background:#fdf1d8;color:#594600;pointer-events:none;box-shadow:0 1px 3px rgba(0,0,0,.15)">Preview · sample data · changes stay in this page</div></body>');
{
  let pv = read(path.join(root, 'menu-preview.html'));
  pv = pv.replace(/<link\b[^>]*rel="stylesheet"[^>]*href="([^"]+)"[^>]*>/gi, (tag, url) => '<style>' + read(path.join(root, url.split('?')[0])) + '</style>');
  pv = pv.replace(/<script src="([^"]+)"><\/script>/gi, (_, url) => script(url.startsWith('config.js') ? config : read(path.join(root, url.split('?')[0])).replace("e.origin !== location.origin ||", "(e.origin !== location.origin && location.origin !== 'null') ||").replace("parent.postMessage({ type: 'm17-preview-ready' }, location.origin)", "parent.postMessage({ type: 'm17-preview-ready' }, '*')")));
  html = html.replace('src="../menu-preview.html?v=19"', () => 'srcdoc="${esc(window.__M17_SRCDOC)}"');
  html = html.replace('</head>', () => '<script>window.__M17_SRCDOC=' + JSON.stringify(pv).replace(/<\//g, '<\\/') + ';</script></head>');
  html = html.replace("f?.contentWindow?.postMessage({ type: 'm17-preview', payload: payload() }, location.origin)", "f?.contentWindow?.postMessage({ type: 'm17-preview', payload: payload() }, location.protocol === 'file:' ? '*' : location.origin)");
  html = html.replace("const onMsg = e => { if (e.origin === location.origin && ", "const onMsg = e => { if ((e.origin === location.origin || location.origin === 'null' || e.origin === 'null') && ");
}
const out = path.resolve(__dirname, '..', 'Restaurant-Workspace-Preview-v19.html');
fs.writeFileSync(out, html);
console.log('Wrote', out, (html.length / 1024).toFixed(0) + ' KB');
